def is_good_triple(x, y, z):
    # Check if (x+1)^y is divisible by x^z + 1
    numerator = (x + 1)**y
    denominator = x**z + 1

    # Since x, y, z are positive integers, both numerator and denominator are positive integers.
    if denominator == 0:
        # This should not happen given the constraints x>=1, z>=1
        return False

    return numerator % denominator == 0

good_triples = []
for x in range(1, 6):
    for y in range(1, 6):
        for z in range(1, 6):
            if is_good_triple(x, y, z):
                good_triples.append((x, y, z))

print("Good Triples found (1<=x<=5, 1<=y,z<=5):")
for triple in good_triples:
    print(triple)

# Grouping by x for pattern analysis
patterns_by_x = {1: [], 2: [], 3: [], 4: [], 5: []}
for triple in good_triples:
    x, y, z = triple
    patterns_by_x[x].append((y, z))

print("\nPatterns by x:")
for x in sorted(patterns_by_x.keys()):
    print(f"x={x}: {patterns_by_x[x]}")

def check_good_triple(x, y, z):
    """Checks if (x, y, z) is a good triple."""
    # Numerator: (x+1)^y
    numerator = (x + 1)**y
    # Denominator: x^z + 1
    denominator = x**z + 1

    # Check divisibility. Since x, y, z are positive, both numerator and denominator are positive integers.
    if denominator == 0:
        # Should not happen since x >= 1, z >= 1
        return False

    return numerator % denominator == 0

good_triples = []
z_results = {1: [], 2: [], 3: [], 4: [], 5: []}

# Constraints: 1 <= z <= 5, 1 <= x <= 5, 1 <= y <= 5
for z in range(1, 6):
    for x in range(1, 6):
        for y in range(1, 6):
            if check_good_triple(x, y, z):
                triple = (x, y, z)
                good_triples.append(triple)
                z_results[z].append(triple)

print("--- All Good Triples Found ---")
print(sorted(good_triples))

print("\n--- Good Triples Grouped by z ---")
for z in range(1, 6):
    print(f"z={z}: {sorted(z_results[z])}")
